-- Ids are UUIDv7 generated by the backend (time ordered, so they double as cursors).
-- Money is stored as integer cents (ZAR).

CREATE TYPE session_kind     AS ENUM ('web', 'app');
CREATE TYPE venture_status   AS ENUM ('pending', 'approved', 'suspended');
CREATE TYPE member_role      AS ENUM ('owner', 'member');
CREATE TYPE listing_kind     AS ENUM ('product', 'service');
CREATE TYPE listing_status   AS ENUM ('draft', 'pending_review', 'published', 'rejected', 'archived');
CREATE TYPE order_status     AS ENUM ('pending_payment', 'paid', 'accepted', 'fulfilled', 'cancelled', 'refunded');
CREATE TYPE payment_status   AS ENUM ('pending', 'complete', 'cancelled', 'failed');

-- ---------------------------------------------------------------- identity

CREATE TABLE users (
    id             uuid PRIMARY KEY,
    entra_oid      uuid NOT NULL UNIQUE,
    tenant_id      uuid NOT NULL,
    email          text NOT NULL,
    display_name   text NOT NULL,
    is_admin       boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    last_login_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX users_email_idx ON users (lower(email));

CREATE TABLE sessions (
    id            uuid PRIMARY KEY,
    token_hash    bytea NOT NULL UNIQUE,
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    kind          session_kind NOT NULL,
    user_agent    text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL
);
CREATE INDEX sessions_user_idx ON sessions (user_id);

-- In-flight OIDC logins (state -> nonce/PKCE). Single use, short lived.
CREATE TABLE login_attempts (
    state               text PRIMARY KEY,
    nonce               text NOT NULL,
    pkce_verifier       text NOT NULL,
    silent              boolean NOT NULL,
    return_to           text NOT NULL,
    app_redirect_uri    text,           -- set for native app logins
    app_code_challenge  text,           -- app's own PKCE challenge, bound to the handoff code
    expires_at          timestamptz NOT NULL
);

-- One-time codes handed to the native app via its redirect URI.
CREATE TABLE app_handoffs (
    code_hash       bytea PRIMARY KEY,
    user_id         uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    code_challenge  text NOT NULL,
    expires_at      timestamptz NOT NULL
);

-- ---------------------------------------------------------------- catalogue

CREATE TABLE ventures (
    id             uuid PRIMARY KEY,
    slug           text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    name           text NOT NULL,
    description    text NOT NULL DEFAULT '',
    logo_key       text,
    contact_email  text,
    contact_phone  text,
    status         venture_status NOT NULL DEFAULT 'pending',
    status_reason  text,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE venture_members (
    venture_id  uuid NOT NULL REFERENCES ventures (id) ON DELETE CASCADE,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role        member_role NOT NULL,
    added_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (venture_id, user_id)
);
CREATE INDEX venture_members_user_idx ON venture_members (user_id);

CREATE TABLE categories (
    id    serial PRIMARY KEY,
    slug  text NOT NULL UNIQUE,
    name  text NOT NULL
);

CREATE TABLE listings (
    id                uuid PRIMARY KEY,
    venture_id        uuid NOT NULL REFERENCES ventures (id),
    kind              listing_kind NOT NULL,
    title             text NOT NULL,
    description       text NOT NULL DEFAULT '',
    category_id       integer REFERENCES categories (id),
    price_cents       bigint NOT NULL CHECK (price_cents >= 0),
    stock             integer CHECK (stock >= 0),          -- NULL = unlimited (e.g. services)
    status            listing_status NOT NULL DEFAULT 'draft',
    rejection_reason  text,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    search            tsvector GENERATED ALWAYS AS (
                          setweight(to_tsvector('english', title), 'A') ||
                          setweight(to_tsvector('english', description), 'B')
                      ) STORED
);
CREATE INDEX listings_venture_idx ON listings (venture_id);
CREATE INDEX listings_published_idx ON listings (id DESC) WHERE status = 'published';
CREATE INDEX listings_search_idx ON listings USING gin (search);

CREATE TABLE listing_images (
    id            uuid PRIMARY KEY,
    listing_id    uuid NOT NULL REFERENCES listings (id) ON DELETE CASCADE,
    object_key    text NOT NULL UNIQUE,
    content_type  text NOT NULL,
    size_bytes    bigint NOT NULL,
    position      integer NOT NULL DEFAULT 0,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX listing_images_listing_idx ON listing_images (listing_id, position);

-- ---------------------------------------------------------------- orders

CREATE TABLE orders (
    id           uuid PRIMARY KEY,
    buyer_id     uuid NOT NULL REFERENCES users (id),
    venture_id   uuid NOT NULL REFERENCES ventures (id),
    status       order_status NOT NULL DEFAULT 'pending_payment',
    total_cents  bigint NOT NULL CHECK (total_cents >= 0),
    note         text,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX orders_buyer_idx ON orders (buyer_id, id DESC);
CREATE INDEX orders_venture_idx ON orders (venture_id, id DESC);
CREATE INDEX orders_pending_idx ON orders (created_at) WHERE status = 'pending_payment';

CREATE TABLE order_items (
    order_id          uuid NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    listing_id        uuid NOT NULL REFERENCES listings (id),
    title_snapshot    text NOT NULL,
    unit_price_cents  bigint NOT NULL,
    quantity          integer NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (order_id, listing_id)
);

CREATE TABLE payments (
    id              uuid PRIMARY KEY,               -- sent to PayFast as m_payment_id
    order_id        uuid NOT NULL REFERENCES orders (id),
    provider        text NOT NULL DEFAULT 'payfast',
    checkout_token  bytea NOT NULL UNIQUE,          -- sha256 of the one-time checkout page token
    client          session_kind NOT NULL,          -- where to send the buyer after checkout
    amount_cents    bigint NOT NULL,
    status          payment_status NOT NULL DEFAULT 'pending',
    pf_payment_id   text UNIQUE,
    raw_itn         jsonb,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payments_order_idx ON payments (order_id);

-- ---------------------------------------------------------------- audit

CREATE TABLE audit_log (
    id           uuid PRIMARY KEY,
    actor_id     uuid REFERENCES users (id),        -- NULL = system (e.g. PayFast ITN, expiry job)
    action       text NOT NULL,
    target_type  text NOT NULL,
    target_id    uuid NOT NULL,
    reason       text,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_target_idx ON audit_log (target_type, target_id);
